MStatus initializePlugin(MObject obj) {
    MFnPlugin plugin(obj, "mpynode-native", "1.0+0fd741e99f5f", "Any");
    MStatus _st = plugin.registerNode("spine", Spine::id, Spine::creator, Spine::initialize);
    if (!_st) return _st;
    MStatus _cs_SpineBuildSystemCmd = plugin.registerCommand("spineBuildSystem", SpineBuildSystemCmd::creator, SpineBuildSystemCmd::newSyntax); if (!_cs_SpineBuildSystemCmd) return _cs_SpineBuildSystemCmd;
    MStatus _cs_SpineCmd = plugin.registerCommand("spine", SpineCmd::creator, SpineCmd::newSyntax); if (!_cs_SpineCmd) return _cs_SpineCmd;
    return _st;
}

MStatus uninitializePlugin(MObject obj) {
    MFnPlugin plugin(obj);
    plugin.deregisterCommand("spineBuildSystem");
    plugin.deregisterCommand("spine");
    return plugin.deregisterNode(Spine::id);
}
